INSERT INTO `knowledge_chapter` (`id`, `course_id`, `parent_id`, `chapter_code`, `title`, `level`, `sort_order`, `description`, `summary`) VALUES
(54, 1, 0, '3', '第 3 章 控制结构', 1, 3, '本章介绍 Java 语言的控制结构：先说明顺序、分支、循环三种程序执行流程，再依次讲解选择结构的单分支 if 语句、双分支 if-else 语句、多分支结构（嵌套 if 语句、多分支 if-else 语句、switch 语句）以及 Java SE 14 起 switch 的新形式，并以判断闰年、判断生肖属相为例说明选择结构的应用；随后讲解循环结构的 while 循环、do-while 循环、for 循环、嵌套循环以及循环中的 break 语句与 continue 语句，给出超市结账、九九乘法表等程序；最后通过求 π 值、百钱买百鸡问题、输出素数三个示例综合应用选择与循环结构，附课程思政案例与本章习题（选择题、填空题、简答题、分析题、编程题）。', 'Java 语言程序在执行时，有三种常见的执行流程：顺序执行流程、分支执行流程、循环执行流程，它们对应的控制结构分别是：顺序结构、选择结构和循环结构。\n顺序执行流程是指程序按照语句出现的顺序，从前往后按照顺序逐条执行。顺序执行流程是最基本的程序执行流程，Java 程序中的语句按照出现的先后顺序，自动构成一种顺序结构，第二章的示例程序也体现了顺序执行流程。因此，本章不再单独说明顺序结构。\n分支执行流程是指根据逻辑条件选择要执行的分支。例如，一个商场举行促销活动，购物金额达到 1000 元以上，可以打八折；达到 500 元且不超过 1000 元的，可以打九折；低于 500 元的，可以打九五折。对于这样的编程问题，需要采用分支执行流程。Java 语言提供了多种选择结构来实现对分支执行流程的控制，包括：单分支结构、双分支结构、多分支结构。\n循环执行流程是指根据逻辑条件，反复地执行一段代码或一个语句块。例如，我们想把一个字符串“welcome to Java！”输出 500 次，如果没有循环语句，对于相同的代码就要重复写 500 次，这是非常繁琐和低效的。Java 语言提供了三种类型的循环结构语句：while 循环、do-while 循环、for 循环，对循环执行流程进行控制。'),
(55, 1, 54, '3.1', '选择结构', 2, 1, 'Java 语言的选择结构有三种不同的形式：单分支结构、双分支结构、多分支结构，如图 3-1 所示。多分支结构也有三种不同的形式：嵌套 if 语句、多分支 if-else 语句、switch 语句。（图 3-1　选择结构分类：选择结构分为单分支结构、双分支结构和多分支结构三类，单分支结构对应单分支 if 语句，双分支结构对应双分支 if-else 语句，多分支结构对应嵌套 if 语句、多分支 if-else 语句和 switch 语句）', NULL),
(56, 1, 55, '3.1.1', '单分支结构', 3, 1, NULL, NULL),
(57, 1, 55, '3.1.2', '双分支结构', 3, 2, NULL, NULL),
(58, 1, 55, '3.1.3', '多分支结构：嵌套 if 和多分支 if-esle', 3, 3, NULL, NULL),
(59, 1, 55, '3.1.4', '多分支结构：switch', 3, 4, NULL, NULL),
(60, 1, 55, '3.1.5', 'switch 新特性', 3, 5, NULL, NULL),
(61, 1, 55, '3.1.6', '示例：判断闰年', 3, 6, NULL, NULL),
(62, 1, 55, '3.1.7', '示例：判断生肖属相', 3, 7, NULL, NULL),
(63, 1, 54, '3.2', '循环结构', 2, 2, '人们在处理问题时，常常遇到需要反复执行某些操作的情况。例如，某段信息重复输出 100 次，寻找前 50 个素数并输出，查找并输出 1-1000 范围内的水仙花数等。这就需要用到循环结构。Java 语言提供了 3 种循环结构：while 循环、do-while 循环、for 循环。', NULL),
(64, 1, 63, '3.2.1', 'while 循环', 3, 1, NULL, NULL),
(65, 1, 63, '3.2.2', 'do-while 循环', 3, 2, NULL, NULL),
(66, 1, 63, '3.2.3', 'for 循环', 3, 3, NULL, NULL),
(67, 1, 63, '3.2.4', '嵌套循环', 3, 4, NULL, NULL),
(68, 1, 63, '3.2.5', '循环中的 break 语句', 3, 5, NULL, NULL),
(69, 1, 63, '3.2.6', '循环中的 continue 语句', 3, 6, NULL, NULL),
(70, 1, 63, '3.2.7', '示例：求 π 值', 3, 7, NULL, NULL),
(71, 1, 63, '3.2.8', '示例：百钱买百鸡问题', 3, 8, NULL, NULL),
(72, 1, 63, '3.2.9', '示例：输出素数', 3, 9, NULL, NULL),
(73, 1, 54, '3.3', '课程思政案例', 2, 3, '对应章节：3.3 循环结构', NULL);
