(59, 64, 'while 循环', NULL, 1, 'while 循环,循环继续条件,循环体,无限循环,计数器控制的循环', 'P.112-113', 1),
(60, 65, 'do-while 循环', NULL, 1, 'do-while 循环,后测循环,标记值控制的循环,浮点数相等比较', 'P.113-115', 1),
(61, 66, 'for 循环', NULL, 1, 'for 循环,初始化表达式,每次迭代后表达式,循环控制变量,作用域', 'P.115-117', 1),
(62, 67, '嵌套循环', NULL, 1, '嵌套循环,两层循环,外层循环,内层循环', 'P.117-118', 1),
(63, 68, '循环中的 break 语句', NULL, 1, 'break 语句,用户确认的循环,终止当前层循环', 'P.118-120', 1),
(64, 69, '循环中的 continue 语句', NULL, 1, 'continue 语句,本次迭代,循环继续条件', 'P.120-121', 1),
(65, 70, '示例：求 π 值', NULL, 1, '求 π 值,级数累加,分子分母,绝对值', 121, 1),
(66, 71, '示例：百钱买百鸡问题', NULL, 1, '百钱买百鸡,三重循环,穷举,循环优化', 'P.121-122', 1),
(67, 72, '示例：输出素数', NULL, 1, '素数,合数,isPrime,伪码,常量', 'P.122-124', 1),
(68, 73, '课程思政案例', NULL, 1, '课程思政,矛盾对立统一,螺旋上升,科学发展观', 125, 1),
