INSERT INTO `knowledge_concept` (`id`, `chapter_id`, `name`, `definition`, `difficulty`, `page`, `page_order`) VALUES
(102, 54, '顺序执行流程', '顺序执行流程是指程序按照语句出现的顺序，从前往后按照顺序逐条执行。', 1, 101, 1),
(103, 54, '分支执行流程', '分支执行流程是指根据逻辑条件选择要执行的分支。', 1, 101, 2),
(104, 54, '循环执行流程', '循环执行流程是指根据逻辑条件，反复地执行一段代码或一个语句块。', 1, 101, 3),
(105, 55, '选择结构', 'Java 语言的选择结构有三种不同的形式：单分支结构、双分支结构、多分支结构', 1, 102, 1),
(106, 56, '单分支结构', '单分支结构是最简单的选择结构，它只有一个分支，该分支要么被执行，要么被忽略。实现单分支结构的语句是单分支 if 语句。', 1, 102, 1),
(107, 56, '单分支 if 语句', '单分支 if 语句的意思是当且仅当指定的布尔表达式值为 true 时，执行 if 语句中括起来的一条或多条语句（这里的一条或多条语句也可以称为语句组）', 1, 102, 2),
(108, 56, 'if 语句的圆括号', '需要注意的是，if 语句中的布尔表达式必须用圆括号括住，否则，就会产生编译错误。', 1, 102, 3),
(109, 57, '双分支结构', '双分支结构根据指定布尔表达式是真或假，选择执行不同的操作，可由双分支 if-else 语句实现。', 1, 103, 1),
(110, 57, '双分支 if-else 语句', '该一般形式的流程如图 3-3 所示。当指定布尔表达式计算结构为 true 时，执行语句组 1；否则，执行语句组 2。', 1, 104, 1),
(111, 57, '条件运算符', '双分支 if-else 语句在一些使用场景，可以由条件运算符进行精简。', 1, 104, 2),
(112, 58, '多分支结构', '在一些编程场景，程序在执行时，如果供选择执行的路径超过两个分支，就要用到多分支结构。Java 语言支持多分支结构的形式有三种：一是嵌套 if 语句，二是多分支 if-else 语句，三是 switch 语句。', 1, 104, 1),
(113, 58, '嵌套 if 语句', '嵌套 if 语句是指在单分支 if 语句或双分支 if-else 语句的语句组中嵌入单分支 if 语句或双分支 if-else 语句，而内层的单分支 if 语句或双分支 if-else 语句的语句组可以继续嵌入单分支 if 语句或双分支 if-else 语句。Java 语言对嵌套 if 语句的嵌套深度没有限制。', 1, 104, 2),
(114, 58, 'else 与 if 的配对', '在嵌套 if 语句中，else 总是与它上面最近的、且未配对的 if 配对。', 1, 105, 1),
(115, 58, '多分支 if-else 语句', '这种书写样式，也被称为多分支 if-else 语句，可以避免深度缩进，提升程序的易读性。', 1, 105, 2),
(116, 59, 'switch 语句', '当处理同一个表达式的多个选项时，多分支 if-else 语句虽然可以处理，但是代码会显得臃肿。Java 语言提供 switch 语句来更好地处理这种情况。', 1, 106, 1),
(117, 59, 'switch 表达式的类型限制', 'switch 语句中的表达式必须能计算出一个 char、byte、short、int、枚举或者 String 类型的值，并且必须总是用圆括号括住。', 1, 107, 1),
(118, 59, '常量表达式', 'case 语句中，关键字 case 之后只能是常量表达式。更具体地说，这里的表达式不能包含变量。', 1, 107, 2),
(119, 59, 'default 语句', 'default 语句是可选的，当所有 case 语句的值和表达式的值无法匹配时，就执行 default 对应的语句组 N+1。', 1, 107, 3),
(120, 59, '直通（fallthrough）行为', '因此，switch 表达式的值是 10 和 9，执行的语句组是相同的。这种现象也称为直通（fallthrough）行为。', 1, 108, 1),
(121, 60, 'switch 新形式', '从 Java SE 14 开始，switch 可以采用新的形式，例如，改写上面输出工作日、周末的例子，其代码如下所示：', 1, 108, 1),
(122, 60, 'switch 表达式', '另外，从 Java SE 14 开始，switch 表达式还可以用在赋值语句的右边给一个变量赋值，并且这个变量可以在多个值中做出选择。', 1, 109, 1),
(123, 60, 'default 的必要性', '注意：switch 表达式在使用整数或 String 值作为圆括号中的操作数时，必须要有一个 default，因为无论操作数是什么，这个表达式都必须要具有一个值。', 1, 110, 1),
(124, 60, '枚举类型', 'switch 表达式还可以使用枚举类型（见 9.2 节）。', 1, 110, 2),
(125, 61, '闰年与平年', '在公历中，闰年有 366 天，二月份是 29 天，平年有 365 天，二月份是 28 天。一个年份是否闰年的判断条件是：可以被 4 整除但不能被 100 整除，或者可以被 400 整除。', 1, 110, 1),
(126, 62, '生肖属相', '在我国，十二生肖，又称为属相，是十二地支的形象化代表', 1, 111, 1),
(127, 62, '年份对 12 取余', '生肖是基于 12 年一个周期，因此，可以用年份对 12 取余即可。', 1, 111, 2),
(128, 63, '循环结构', 'Java 语言提供了 3 种循环结构：while 循环、do-while 循环、for 循环。', 1, 112, 1),
(129, 64, '循环继续条件', '循环继续条件是一个布尔表达式，总是放在圆括号中。循环体是循环中包含的重复执行的一条或多条语句。', 1, 112, 1),
(130, 64, '无限循环', '该循环会成为无限循环，无限循环是指循环体无限次执行的循环。这是因为该循环的循环继续条件始终是 true。', 1, 113, 1),
(131, 64, '计数器控制的循环', '程序清单 3-7 所示示例使用计数变量 i 对循环次数进行计数，这种类型的循环也称为计数器控制的循环。计数器控制的循环是确切知道循环次数的。', 1, 113, 2),
(132, 65, 'do-while 循环', 'do-while 循环与 while 循环基本一样，不同之处在于，do-while 循环先执行循环体一次，再判断循环继续条件。因此，do-while 循环也称为后测循环，而 while 循环称为前测循环。', 1, 113, 1),
(133, 65, '标记值控制的循环', '如果一个循环使用标记值来控制循环的结束，那么这个循环可被称为标记值控制的循环。', 1, 115, 1),
(134, 65, '浮点数相等比较控制循环', '这是因为浮点数都是近似值，使用浮点数相等比较来控制循环，可能会出现不精确的循环次数和不准确的结果。', 1, 115, 2),
(135, 66, 'for 循环', 'for 循环与 while 循环是等价的，相对于 while 循环而言，是一种更加简明的形式。', 1, 115, 1),
(136, 66, '循环控制结构体', '其后的圆括号内是由三个部分构成的循环控制结构体，这三个部分用分号分隔，它们是：初始化表达式、循环继续条件、每次迭代后表达式。', 1, 116, 1),
(137, 66, 'for 循环变量的作用域', 'for 循环的初始化表达式中声明和初始化的变量仅仅作用于 for 循环，在 for 循环之外就无效了。', 1, 117, 1),
(138, 66, '循环继续条件的省略', '另外，for 循环的循环继续条件如果被省略，那么隐式地认为循环继续条件为 true。', 1, 117, 2),
(139, 67, '嵌套循环', '嵌套循环是指一个循环体内包含一个或多个内层循环，每个内层循环还可以包含零个或多个内层循环。每当外层循环执行一次，其内部的内层循环都会重新开始执行。', 1, 117, 1),
(140, 67, '两层循环', '当嵌套循环层次是两层时，也可以称为两层循环；当嵌套循环层次是三层时，可以称为三层循环。', 1, 117, 2),
(141, 68, '循环中的 break 语句', '循环结构中如果执行到 break 语句，会立即终止当前循环的执行。', 1, 118, 1),
(142, 68, '用户确认的循环', '这种由用户输入确认的循环，可称为用户确认的循环。', 1, 119, 1),
(143, 68, 'break 在嵌套循环中的作用范围', '需要注意的是，在嵌套循环中，break 语句用于终止当前层的循环，而不是终止整个循环。', 1, 119, 2),
(144, 69, '循环中的 continue 语句', '循环结构中如果执行到 continue 语句，会立即结束当前循环的本次执行，然后，继续当前循环的下一次执行。', 1, 120, 1),
(145, 70, '求 π 值的级数计算', '本例要求计算到上述计算公式的最后一项的绝对值小于等于 10⁻⁷ 时，才终止计算。', 1, 121, 1),
(146, 71, '百钱买百鸡问题', '百钱买百鸡问题是一个经典的数学问题，其描述如下：100 元钱要买 100 只鸡，公鸡 5 元一只，母鸡 3 元一只，小鸡 1 元三只，问可以买到多少只公鸡、母鸡和小鸡？', 1, 121, 1),
(147, 72, '素数', '素数也称为质数，是指只能被 1 和它自身整除且大于 1 的整数。', 1, 122, 1),
(148, 72, '合数', '合数是指除了能被 1 和自身整除，还能被其他整数（0 除外）整除，且大于 1 的整数。', 1, 122, 2),
(149, 72, '伪码', '上述算法描述结合了自然语言以及 Java 语言语法，也是一种伪码描述。', 1, 123, 1),
(150, 73, '课程思政案例', '针对上述目标，运用类比分析的方法，用分支结构印证自然辨证法二分法的方法论，用循环结构印证马克思主义中社会发螺旋上升规律，加深学生对马克思主义的理解和对理论的灵活运用能力，培养学生科学发展观，加深学生对社会发展规律的认识，坚定学生社会主义和共产主义的理想信念。', 1, 125, 1),
(151, 73, '矛盾的对立统一', '马克思主义认为，矛盾总是从一个事物内部产生，这是矛盾统一性的表现；其后会走向两个完全不同的发展道路，这是矛盾对立性的表现。', 1, 125, 2);
INSERT INTO `knowledge_code_snippet` (`id`, `chapter_id`, `title`, `code`, `is_key_example`, `page`, `page_order`) VALUES
(521, 56, '单分支 if 语句的一般形式', 'if(布尔表达式){\n      一条或多条语句\n}', 0, 102, 1),
(522, 56, '单分支 if 语句示例：判断 x 是否为偶数', 'if( x % 2 == 0 ){\n      System.out.println(x + "是偶数");\n}', 0, 102, 2),
(523, 56, '省略花括号的单分支 if 语句', 'if( x % 2 == 0 )\n      System.out.println(x + "是偶数");', 0, 102, 3),
(524, 56, 'if 后布尔表达式缺少圆括号的编译错误示例', 'if x % 2 == 0 {\n      System.out.println(x + "是偶数");\n}', 0, 102, 4),
