(118, 67, '程序清单 3-10　PrintMultiplyTable.java', '1  public class PrintMultiplyTable {\n2    public static void main(String[] args){\n3        System.out.println("\\t\\t\\t 九九乘法表");\n4        for(int i = 1; i <= 9; i++){\n5           System.out.print("\\t"+i);\n6        }\n7        System.out.println();\n8        for(int i = 0; i < 80; i++){\n9           System.out.print("*");\n10       }\n11       System.out.println();\n12       for(int i = 1; i <= 9; i++){\n13           System.out.print(i+"|\\t");\n14           for(int j = 1; j <= i; j++){\n15               System.out.print(j + "×" + i + "=" + j*i + "\\t");\n16               if(i == j)\n17                   System.out.println();\n18           }\n19       }\n20    }\n21  }', 0, 117, 50),
(119, 68, '程序清单 3-11　AddTestBreak.java', '1   public class AddTestBreak {\n2     public static void main(String[] args) {\n3       Scanner input = new Scanner(System.in);\n4       do {\n5         int num1 = (int)(Math.random() * 100);\n6         int num2 = (int)(Math.random() * 100);\n7         System.out.printf("请输入%d + %d 的和：", num1, num2);\n8         int sum = input.nextInt();\n9         String output = num1 + "+" + num2 + "=" + sum;\n10        output += num1 + num2 == sum ? " 回答正确！":" 回答错误！";\n11        System.out.println(output);\n12        System.out.print("退出请输入 N 或 n(继续请输入其他字符)：");\n13        char c = input.next().charAt(0);\n14        if(Character.toUpperCase(c) == \'N\') {\n15              System.out.println("训练结束！");\n16              break;\n17        }\n18      }while(true);\n19    }\n20  }', 0, 118, 51),
